ahora=$(date +"%Y-%m-%d-%H-%M-%S");echo $ahora;destino="AvilaprovPoblaciones.csv";destino1="${ahora}avilapob.txt";destino2=$(echo ${destino1} | sed 's/\-//g');destino3=$(echo ${destino2} | sed 's/\.txt//g');echo "${destino} ${destino1} $destino2 ${destino3}";cat ${destino} | while IFS=";" read ayto total ano poblacion;do if [[ "$ayto" == "Municipios" ]]; then echo "Municipios;Total" >>${destino1} ;else poblacion=$(echo ${poblacion} | sed 's/\.//g');echo "${ayto:5};${poblacion}" >>${destino1};fi;done;cp $destino1 $destino2;echo -e "\n\nAytos mayores a 10.000 habitantes";csvsql -d ";" --query "SELECT * FROM '${destino3}' WHERE Total > 10000" ${destino2} | csvsort -d "," -c 2 -r | csvlook -d ",";echo -e "\n\nAytos mayores a 5.000 habitaciones";csvsql -d ";" --query "SELECT * FROM '${destino3}' WHERE Total > 5000 AND Total <= 10000" ${destino2} | csvsort -d "," -c 2 -r  | csvlook -d ",";echo -e "\n\nAytos mayores a 1.000 habitantes";csvsql -d ";" --query "SELECT * FROM '${destino3}' WHERE Total >= 1000 AND Total <= 5000" ${destino2} | csvsort -d "," -c 2 -r | csvlook -d ","
